-- ENUM vs TEXT + CHECK: an enum is compact (4 bytes) and self-documenting, but removing
-- or renaming a value later is painful. Roles are stable, so an enum is a fair choice here.
CREATE TYPE user_role AS ENUM ('RIDER', 'DRIVER', 'ADMIN');

CREATE TABLE users (
  -- UUIDs (vs BIGSERIAL) can be generated by any service without asking the DB,
  -- and don't leak "we have 1,204 users". gen_random_uuid() is built into PG13+.
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  -- UNIQUE creates a B-tree index automatically; that index is what makes login lookups fast.
  -- TEXT UNIQUE is case-sensitive ('A@x.com' != 'a@x.com'), so the CHECK forces the app
  -- to normalize. The DB is the last line of defense if some code path forgets.
  email         TEXT NOT NULL UNIQUE CHECK (email = lower(email)),
  password_hash TEXT NOT NULL,
  name          TEXT NOT NULL,
  role          user_role NOT NULL,
  -- TIMESTAMPTZ stores an absolute instant (UTC internally). Plain TIMESTAMP has no zone
  -- and silently means different things on servers in different time zones.
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 1:1 with users. Using user_id as the PK (instead of its own id) makes "one profile
-- per user" a structural guarantee, not something the app has to check.
CREATE TABLE driver_profiles (
  user_id       UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  vehicle_no    TEXT NOT NULL UNIQUE,
  vehicle_type  TEXT NOT NULL,
  is_active     BOOLEAN NOT NULL DEFAULT true
);

